WITH filtered AS (SELECT id, store_name, city, region, opened_date, sqft, CAST(sqft AS STRING) AS sqft_str, COALESCE(region, 'NONE') AS region_filled FROM stores WHERE opened_date > TO_DATE('2023-06-12') AND region IS NOT NULL), enriched AS (SELECT *, NTILE(10) OVER (ORDER BY sqft DESC, id) AS sqft_bucket, SUM(sqft) OVER (PARTITION BY region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_sqft, ROW_NUMBER() OVER (PARTITION BY city ORDER BY opened_date DESC, id) AS event_seq, FIRST_VALUE(sqft, TRUE) OVER (PARTITION BY city, region ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_sqft, ROUND(sqft / SUM(sqft) OVER (PARTITION BY region), 4) AS sqft_share FROM filtered), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY region ORDER BY opened_date NULLS LAST, id) AS rank_in_group FROM enriched) ranked WHERE rank_in_group = 1) SELECT id, store_name, city, region, region_filled, sqft_bucket, cumulative_sqft, first_known_sqft, sqft_share FROM deduped ORDER BY first_known_sqft DESC NULLS FIRST
